/**
 * Session Manager - Cross-Page Session Management
 *
 * Manages session ID persistence across page navigations using localStorage.
 * Tracks page transitions and session metadata for replay continuity.
 *
 * Features:
 * - Persistent session ID (UUID) in localStorage
 * - Cross-page session continuity
 * - Page transition tracking
 * - Session expiration (idle timeout)
 * - Session metadata (start time, page count)
 */
import { sha256Hex, hashHex64 } from './util/hash.js';

export class SessionManager {
    /**
     * Compute a GDPR-friendly session hash for a session id.
     *
     * Prefers a real SHA-256 digest (Web Crypto); falls back to a 64-char
     * djb2 hex when SubtleCrypto is unavailable. Always resolves to a
     * 64-character hex string (matches the API's session_hash contract).
     *
     * Centralised here so the crypto lives with session concerns rather than
     * being duplicated inside the Client.
     *
     * @param {string} sessionId - Session identifier to hash
     * @returns {Promise<string>} 64-character hex hash
     */
    static async computeSessionHash(sessionId) {
        const digest = await sha256Hex(sessionId);
        return digest ?? hashHex64(sessionId);
    }

    /**
     * Synchronous (non-cryptographic) session hash fallback.
     *
     * @param {string} sessionId - Session identifier to hash
     * @returns {string} 64-character hex hash
     */
    static computeSessionHashSync(sessionId) {
        return hashHex64(sessionId);
    }

    /**
     * @param {Object} [config] - Configuration options
     * @param {number} [config.sessionTimeoutMinutes=30] - Session timeout in minutes
     * @param {boolean} [config.debug=false] - Enable debug logging
     */
    constructor(config = {}) {
        this.config = {
            sessionTimeoutMinutes: Math.min(config.sessionTimeoutMinutes || 30, 120),
            debug: config.debug || false,
        };

        // localStorage keys
        this.STORAGE_KEY_SESSION_ID = '_app_logger_session_id';
        this.STORAGE_KEY_SESSION_METADATA = '_app_logger_session_metadata';

        // Session state
        this.sessionId = null;
        this.metadata = {
            startedAt: null,
            lastActivityAt: null,
            pageCount: 0,
            pages: [],
        };

        // Bound navigation handlers, stored so teardown() can removeEventListener
        // them (anonymous handlers would be unremovable and leak on re-init, RML-03).
        this.boundNavigationChange = () => this.handleNavigationChange();
        this.pageTransitionTrackingInstalled = false;

        // Initialize
        this.initialize();

        if (this.config.debug) {
            console.warn('SessionManager initialized', {
                sessionId: this.sessionId,
                metadata: this.metadata,
            });
        }
    }

    /**
     * Initialize session (load or create)
     */
    initialize() {
        try {
            // Try to load existing session
            const loaded = this.loadSession();

            if (!loaded || this.isSessionExpired()) {
                // Create new session
                this.createNewSession();
            } else {
                // Update last activity
                this.updateActivity();
            }

            // Track current page
            this.trackPageView(window.location.href);

            // Set up page transition tracking
            this.setupPageTransitionTracking();
        } catch (error) {
            console.error('SessionManager: Failed to initialize:', error);
            // Fallback: create new session
            this.createNewSession();
        }
    }

    /**
     * Create a new session
     */
    createNewSession() {
        try {
            this.sessionId = this.generateSessionId();
            this.metadata = {
                startedAt: Date.now(),
                lastActivityAt: Date.now(),
                pageCount: 0,
                pages: [],
            };

            this.saveSession();

            if (this.config.debug) {
                console.warn('SessionManager: Created new session', this.sessionId);
            }
        } catch (error) {
            console.error('SessionManager: Failed to create new session:', error);
        }
    }

    /**
     * Load session from localStorage
     *
     * @returns {boolean} True if session loaded successfully
     */
    loadSession() {
        try {
            const sessionId = localStorage.getItem(this.STORAGE_KEY_SESSION_ID);
            const metadataJson = localStorage.getItem(this.STORAGE_KEY_SESSION_METADATA);

            if (!sessionId || !metadataJson) {
                return false;
            }

            const metadata = JSON.parse(metadataJson);

            if (!metadata || !metadata.startedAt) {
                return false;
            }

            this.sessionId = sessionId;
            this.metadata = metadata;

            if (this.config.debug) {
                console.warn('SessionManager: Loaded session', {
                    sessionId,
                    age: this.getSessionAge(),
                });
            }

            return true;
        } catch (error) {
            console.error('SessionManager: Failed to load session:', error);
            return false;
        }
    }

    /**
     * Save session to localStorage
     */
    saveSession() {
        try {
            localStorage.setItem(this.STORAGE_KEY_SESSION_ID, this.sessionId);
            localStorage.setItem(
                this.STORAGE_KEY_SESSION_METADATA,
                JSON.stringify(this.metadata),
            );
        } catch (error) {
            console.error('SessionManager: Failed to save session:', error);
        }
    }

    /**
     * Check if session is expired
     *
     * @returns {boolean}
     */
    isSessionExpired() {
        try {
            if (!this.metadata.lastActivityAt) {
                return true;
            }

            const now = Date.now();
            const lastActivity = this.metadata.lastActivityAt;
            const timeoutMs = this.config.sessionTimeoutMinutes * 60 * 1000;

            return (now - lastActivity) > timeoutMs;
        } catch {
            return true;
        }
    }

    /**
     * Update last activity timestamp
     */
    updateActivity() {
        try {
            this.metadata.lastActivityAt = Date.now();
            this.saveSession();
        } catch (error) {
            console.error('SessionManager: Failed to update activity:', error);
        }
    }

    /**
     * Track page view
     *
     * @param {string} url - Page URL
     * @returns {Object} Page transition event
     */
    trackPageView(url) {
        try {
            // Increment page count
            this.metadata.pageCount++;

            // Add to pages array (keep last 50)
            this.metadata.pages.push({
                url,
                timestamp: Date.now(),
            });

            if (this.metadata.pages.length > 50) {
                this.metadata.pages = this.metadata.pages.slice(-50);
            }

            // Update activity
            this.updateActivity();

            // Create page transition event
            const pageEvent = {
                type: 'pageTransition',
                url,
                timestamp: Date.now(),
                phase: 'before_error',
                sessionId: this.sessionId,
                pageCount: this.metadata.pageCount,
            };

            if (this.config.debug) {
                console.warn('SessionManager: Page view tracked', {
                    url,
                    pageCount: this.metadata.pageCount,
                });
            }

            return pageEvent;
        } catch (error) {
            console.error('SessionManager: Failed to track page view:', error);
            return null;
        }
    }

    /**
     * Set up page transition tracking
     */
    setupPageTransitionTracking() {
        try {
            // Per-instance idempotency: re-running setup would register a second
            // popstate/hashchange pair on the same instance (RML-03).
            if (this.pageTransitionTrackingInstalled) {
                return;
            }

            // Track history API navigation (pushState, replaceState).
            // Guard against double-wrapping by THIS module on re-init / HMR (JS-2):
            // a per-module sentinel ensures we wrap at most once. A distinct
            // sentinel from BreadcrumbCollector's is used so both modules' wrappers
            // can coexist (one may layer over the other) without losing behavior.
            // The sentinel carries the original ref for teardown.
            if (!history.pushState._appLoggerSessionWrapped) {
                const originalPushState = history.pushState;
                this._originalPushState = originalPushState;

                const wrappedPushState = (...args) => {
                    originalPushState.apply(history, args);
                    this.handleNavigationChange();
                };
                wrappedPushState._appLoggerSessionWrapped = true;
                wrappedPushState._appLoggerOriginal = originalPushState;
                // Tag the wrapper with THIS instance so teardown only unwraps
                // its own wrapper (two SDK instances must not unwrap each
                // other's, JS-4).
                wrappedPushState._appLoggerSessionOwner = this;
                this._ownsPushStateWrapper = true;
                history.pushState = wrappedPushState;
            }

            if (!history.replaceState._appLoggerSessionWrapped) {
                const originalReplaceState = history.replaceState;
                this._originalReplaceState = originalReplaceState;

                const wrappedReplaceState = (...args) => {
                    originalReplaceState.apply(history, args);
                    this.handleNavigationChange();
                };
                wrappedReplaceState._appLoggerSessionWrapped = true;
                wrappedReplaceState._appLoggerOriginal = originalReplaceState;
                wrappedReplaceState._appLoggerSessionOwner = this;
                this._ownsReplaceStateWrapper = true;
                history.replaceState = wrappedReplaceState;
            }

            // Track popstate (back/forward buttons) and hash changes via stored
            // bound refs so teardown() can remove them.
            window.addEventListener('popstate', this.boundNavigationChange);
            window.addEventListener('hashchange', this.boundNavigationChange);

            this.pageTransitionTrackingInstalled = true;
        } catch (error) {
            console.error('SessionManager: Failed to setup page transition tracking:', error);
        }
    }

    /**
     * Remove the popstate/hashchange listeners and restore history.pushState/
     * replaceState from the stamped _appLoggerOriginal refs. Idempotent and
     * never throws, so repeated enable/disable cycles do not accumulate
     * listeners or history wrappers (RML-03).
     */
    teardownPageTransitionTracking() {
        try {
            window.removeEventListener('popstate', this.boundNavigationChange);
            window.removeEventListener('hashchange', this.boundNavigationChange);

            // Restore history methods ONLY if the live wrapper belongs to THIS
            // instance. With two SDK instances the second's wrapper layers over
            // the first's; tearing down the first must NOT clobber the second's
            // wrapper (which would break the still-active instance, JS-4).
            if (history.pushState && history.pushState._appLoggerSessionWrapped
                && history.pushState._appLoggerOriginal
                && history.pushState._appLoggerSessionOwner === this) {
                history.pushState = history.pushState._appLoggerOriginal;
            }
            this._ownsPushStateWrapper = false;
            if (history.replaceState && history.replaceState._appLoggerSessionWrapped
                && history.replaceState._appLoggerOriginal
                && history.replaceState._appLoggerSessionOwner === this) {
                history.replaceState = history.replaceState._appLoggerOriginal;
            }
            this._ownsReplaceStateWrapper = false;
        } catch (error) {
            console.error('SessionManager: Failed to teardown page transition tracking:', error);
        } finally {
            this.pageTransitionTrackingInstalled = false;
        }
    }

    /**
     * Public teardown alias — removes all listeners/wrappers installed by this
     * SessionManager. Called from sessionReplay.disable()/SDK teardown.
     */
    teardown() {
        this.teardownPageTransitionTracking();
    }

    /**
     * Handle navigation change (for SPA routing)
     */
    handleNavigationChange() {
        try {
            const url = window.location.href;

            if (this.config.debug) {
                console.warn('SessionManager: Navigation detected', url);
            }

            // Track the navigation as a page transition
            this.trackPageView(url);
        } catch (error) {
            console.error('SessionManager: Failed to handle navigation change:', error);
        }
    }

    /**
     * Get current session ID
     *
     * @returns {string}
     */
    getSessionId() {
        return this.sessionId;
    }

    /**
     * Get session metadata
     *
     * @returns {Object}
     */
    getMetadata() {
        return { ...this.metadata };
    }

    /**
     * Get session age in milliseconds
     *
     * @returns {number}
     */
    getSessionAge() {
        if (!this.metadata.startedAt) {
            return 0;
        }

        return Date.now() - this.metadata.startedAt;
    }

    /**
     * Generate a new session ID (UUID v4)
     *
     * @returns {string}
     */
    generateSessionId() {
        try {
            // Use crypto.randomUUID if available (modern browsers)
            if (crypto && crypto.randomUUID) {
                return crypto.randomUUID();
            }

            // Fallback: Generate UUID v4 manually
            return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
                const r = Math.random() * 16 | 0;
                const v = c === 'x' ? r : (r & 0x3 | 0x8);
                return v.toString(16);
            });
        } catch {
            // Last resort: timestamp + random
            return `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
        }
    }

    /**
     * Clear session (force new session on next page load)
     */
    clearSession() {
        try {
            localStorage.removeItem(this.STORAGE_KEY_SESSION_ID);
            localStorage.removeItem(this.STORAGE_KEY_SESSION_METADATA);

            this.sessionId = null;
            this.metadata = {
                startedAt: null,
                lastActivityAt: null,
                pageCount: 0,
                pages: [],
            };

            if (this.config.debug) {
                console.warn('SessionManager: Session cleared');
            }
        } catch (error) {
            console.error('SessionManager: Failed to clear session:', error);
        }
    }

    /**
     * Extend session (reset idle timeout)
     */
    extendSession() {
        try {
            this.updateActivity();

            if (this.config.debug) {
                console.warn('SessionManager: Session extended');
            }
        } catch (error) {
            console.error('SessionManager: Failed to extend session:', error);
        }
    }

    /**
     * Get session info for debugging
     *
     * @returns {Object}
     */
    getSessionInfo() {
        return {
            sessionId: this.sessionId,
            age: this.getSessionAge(),
            ageMinutes: Math.floor(this.getSessionAge() / 1000 / 60),
            isExpired: this.isSessionExpired(),
            pageCount: this.metadata.pageCount,
            recentPages: this.metadata.pages.slice(-5),
            timeoutMinutes: this.config.sessionTimeoutMinutes,
        };
    }
}
